const BASE=(()=>{try{const el=[...document.scripts].find(x=>/(^|\/)app\.js(?:\?|$)/.test(x.getAttribute('src')||''));if(!el)return'';const dir=new URL(el.getAttribute('src'),location.href).pathname.replace(/\/assets\/js\/app\.js$/,'').replace(/\/app\.js$/,'');return dir==='/'?'':dir}catch(e){return''}})();const url=p=>typeof p==='string'&&p.charAt(0)==='/'?BASE+p:p;const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const root=$('#root');let route=location.pathname.replace(/\/$/,'')||'/';if(BASE&&(route===BASE||route.startsWith(BASE+'/')))route=route.slice(BASE.length)||'/';const aliases={'/prihlaseni':'/login','/registrace':'/register','/herni-mody':'/game-modes','/funkce':'/features'};route=aliases[route]||route;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let profile={first:'Alex',last:'Novák',username:'alex180',email:'alex@example.cz',avatar:'🎯'};let hasDemoProfile=false;try{const raw=sessionStorage.getItem('dartiqo-demo-profile');if(raw){hasDemoProfile=true;profile={...profile,...JSON.parse(raw)}}}catch{}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('toast-visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),4000)}function modal(title,body){const d=document.createElement('div');d.className='modal-back';d.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><button class="icon-btn ml-auto" data-close aria-label="Zavřít">×</button><h3 class="my-4">${escapeHtml(title)}</h3><p class="text-sm">${body}</p></section>`;document.body.append(d);$('[data-close]',d).onclick=()=>d.remove();d.onclick=e=>{if(e.target===d)d.remove()};d.onkeydown=e=>{if(e.key==='Escape')d.remove()};$('[data-close]',d).focus()}
const navItems=[['Domů','/'],['Herní módy','/game-modes'],['Trénink','/training'],['Kariéra','/career'],['Online','/online'],['Statistiky','/statistics'],['O Dartiqo','/about']];const brand=()=>'<a class="brand" href="'+url("/")+'"><img src="'+url("/assets/images/logo.png")+'" alt="">dartiqo<span class="text-accent">.</span></a>';const nav=()=>`<header class="nav">${brand()}<nav class="nav-links">${navItems.map(([n,u])=>`<a href="${url(u)}" class="${route===u?'active':''}">${n}</a>`).join('')}</nav><div class="flex items-center gap-3"><button class="icon-btn" data-theme aria-label="Přepnout světlý a tmavý režim">◐</button><a class="text-[11px] hidden sm:block" href="${url("/login")}">Přihlásit se</a><a class="btn hidden sm:inline-flex" href="${url("/register")}">Začít hrát ↗</a><button class="icon-btn xl:hidden" id="menu-toggle" aria-expanded="false" aria-label="Otevřít menu">☰</button></div></header>`;const footer=()=>`<footer class="footer"><div class="container flex flex-col md:flex-row justify-between gap-8">${brand()}<div class="footer-links">${[['Funkce','/features'],['Turnaje','/tournaments'],['Žebříčky','/leaderboards'],['Kontakt','/contact'],['Demo aplikace','/app']].map(([n,u])=>`<a href="${url(u)}">${n}</a>`).join('')}</div><span class="text-[10px] text-zinc-500">© 2026 Dartiqo · Designové demo</span></div></footer>`;const intro=(ey,h,p)=>`<section class="container page-head"><span class="eyebrow">${ey}</span><h1>${h}</h1><p>${p}</p></section>`;const cta=()=>`<section class="container pb-20"><div class="rounded-[32px] bg-accent text-black p-9 md:p-14 flex flex-col md:flex-row gap-8 justify-between items-start md:items-center"><h2>Další kapitola?<br>Ta je tvoje.</h2><a href="${url("/register")}" class="btn !bg-black !text-white">Vytvořit profil ↗</a></div></section>`;
const screens=['Dashboard','X01 Match','Herní módy','Trénink','Kariéra','Statistiky'];const bars=()=>'<div class="mini-bars">'+[32,55,42,70,59,84,95].map(n=>`<i style="height:${n}%"></i>`).join('')+'</div>';function phoneUI(i){return `<div class="phone-ui"><span class="text-[8px] text-zinc-400">DARTIQO / ${screens[i].toUpperCase()}</span>${i===0?`<h3 class="mt-2">Ahoj, Alex 👋</h3><div class="mini-yellow"><span class="text-[9px]">TVŮJ DALŠÍ LEVEL</span><h3 class="!text-2xl mt-2">Každý hod<br>tě posouvá.</h3><span class="text-[9px]">LEVEL 12 · 640 / 1 000 XP</span></div><div class="grid grid-cols-2 gap-2"><div class="mini-stat"><b>58.4</b><p class="text-[8px]">Průměr</p></div><div class="mini-stat"><b>32 %</b><p class="text-[8px]">Checkout</p></div></div><div class="mini-row"><b>◎ Rychlá hra</b><span>↗</span></div><div class="mini-row"><b>⚑ Tvoje kariéra</b><span>↗</span></div>`:i===1?`<h3 class="mt-2">501 · Double out</h3><div class="mini-yellow text-center"><span class="text-[9px]">ALEX · NA ŘADĚ</span><div class="text-6xl font-display font-bold my-3">181</div><span class="text-[9px]">PRŮMĚR 60.2 · LEG 2</span></div><div class="mini-row"><b>DartBot · úroveň 4</b><b>245</b></div><div class="grid grid-cols-3 gap-2 mt-4">${[26,41,45,60,85,100,125,140,180].map(n=>`<span class="mini-stat text-center text-xs">${n}</span>`).join('')}</div>`:i===2?`<h3 class="mt-2">Co dnes hrajeme?</h3>${['501 / Klasika','DartBot / Výzva','Cricket / Taktika','Online / Souboj','Kariéra / Tvůj příběh'].map((n,j)=>`<div class="${j===0?'mini-yellow':'mini-row'} text-xs">${n} ↗</div>`).join('')}`:i===3?`<h3 class="mt-2">Čas pro přesnost.</h3><div class="mini-yellow"><div class="text-5xl font-bold">D20</div><p class="text-[10px] mt-2">Dnes míříme na doubly.</p></div>${['Around the Clock','121 Checkout','Bob’s 27','Pressure Training'].map(n=>`<div class="mini-row">${n}<span>↗</span></div>`).join('')}`:i===4?`<h3 class="mt-2">Tvůj příběh.</h3><div class="text-center text-7xl text-accent my-8">♜</div><div class="mini-yellow"><b>Lokální šampion</b><p class="text-[9px]">LEVEL 12 · DALŠÍ CÍL: REGION</p></div><div class="mini-row">Páteční pohár <b>+250 XP</b></div><div class="mini-row">Regionální kvalifikace <b>↗</b></div>`:`<h3 class="mt-2">Lepší než včera.</h3><div class="mini-yellow"><span class="text-[9px]">PRŮMĚR NA 3 ŠIPKY</span><div class="text-5xl font-bold mt-2">58.4</div></div>${bars()}<div class="mini-row">Checkout <b>32 %</b></div><div class="mini-row">Nejvyšší zavření <b>121</b></div>`}<p class="text-[7px] mt-4 text-zinc-500">UKÁZKOVÁ DATA</p></div>`}const phone=(i=0,cls='',id='')=>`<div class="phone ${cls}"><div class="phone-screen"><div class="island"></div><div class="status"><span>9:41</span><span>▮▮▮ ◒ ▰</span></div><div ${id?`id="${id}"`:''}>${phoneUI(i)}</div></div></div>`;
const gameData=[['x01','X01','Od 501 k nule. Každý hod mění hru.','501','Klasika'],['cricket','Cricket','Uzavři čísla. Přečti soupeře. Ovládni terč.','20 / 19','Taktika'],['dartbot','DartBot','Soupeř, který má čas, když ho máš ty.','◉','Sólo'],['local','S kamarádem','Jeden terč. Dva hráči. Nekonečná rivalita.','1 vs 1','Lokálně'],['online','Online','Další soupeř je jen o jeden hod dál.','↗','Multiplayer'],['ranked','Ranked','Každý zápas může změnit tvoje pořadí.','Ⅱ','Soutěž'],['training','Trénink','Krátká výzva. Dlouhodobý posun.','◎','Přesnost'],['career','Kariéra','Od prvního turnaje až po vlastní odkaz.','♜','Příběh']];const gameCards=(limit=8)=>`<div class="bento">${gameData.slice(0,limit).map((g,i)=>`<a class="bento-card ${i===0||i===7?'big':''}" href="${url("/game-modes/"+(g[0]))}"><span class="eyebrow">${g[4]}</span><div class="bento-art">${g[3]}</div><h3>${g[1]} <span class="float-right">↗</span></h3><p class="mt-3">${g[2]}</p></a>`).join('')}</div>`;const stories=[['Score Counter','Počítání nech aplikaci. Ty zůstaň v rytmu hry.',1,'/game-modes/x01'],['DartBot','Vyber soupeře podle svého tempa a zkus ho překonat.',2,'/game-modes/dartbot'],['Online Multiplayer','Přátelský souboj nebo další bod do žebříčku.',1,'/online'],['Training','Trénuj konkrétní slabiny. Nejen oblíbenou dvacítku.',3,'/training'],['AI Coach','Ukázka doporučení, která propojují statistiky s dalším tréninkem.',5,'/training#coach'],['Career Mode','Buduj svůj vlastní šipkařský příběh, turnaj po turnaji.',4,'/career'],['Statistics','Poznej svůj výkon v souvislostech, ne jen podle jednoho legu.',5,'/statistics']];
function home(){return `<section class="reference-hero"><div class="reference-grid"></div><h1 class="reference-title"><span>Tvá hra.</span><span>Tvůj odkaz.</span></h1><div class="reference-glow"></div><div class="hand-showcase" id="hero-product"><img class="hand-photo" src="${url("/assets/images/hand-phone.png")}" alt="Ruka držící telefon s aplikací Dartiqo">${phone(0,'phone-main','hero-screen')}</div></section><section class="showcase-controls container"><div class="flex flex-col md:flex-row justify-between items-center gap-5"><p class="text-sm">Hraj. Trénuj. Soutěž.<br><span class="text-xs">Buduj svou šipkařskou kariéru.</span></p><div class="screen-tabs !mt-0"><button class="icon-btn" data-slide="-1" aria-label="Předchozí obrazovka">←</button>${screens.map((n,i)=>`<button class="chip ${i===0?'active':''}" data-screen="${i}" aria-pressed="${i===0}">${n}</button>`).join('')}<button class="icon-btn" data-slide="1" aria-label="Další obrazovka">→</button></div><a href="#story" class="btn ghost shrink-0">Prozkoumat ↓</a></div></section><div class="ribbon"><span>TVŮJ TERČ</span><span>✳</span><span>TVŮJ POSUN</span><span>✳</span><span>TVŮJ DARTIQO</span></div><section id="story" class="container section"><div class="section-head"><div><span class="eyebrow">VŠECHNO PRO TVOU HRU</span><h2 class="mt-4">Všechny tvoje šipky.<br><span class="text-accent">Jedno místo.</span></h2></div><p>Prohlédni si vizi aplikace. Obrazovky a výsledky jsou interaktivní designové ukázky.</p></div><div class="story-track" id="story-track"><div class="story-stage"><div class="story-phone">${phone(1,'','story-screen')}</div><div class="story-copy"><div class="story-indicators" role="group" aria-label="Vybrat funkci">${stories.map((s,i)=>`<button data-story-jump="${i}" aria-label="${s[0]}" aria-pressed="${i===0}" class="${i===0?'active':''}"><span>0${i+1}</span></button>`).join('')}</div><div id="story-copy-content" aria-live="polite"><article class="story-active"><span class="eyebrow">01 / DARTIQO</span><h3>${stories[0][0]}</h3><p>${stories[0][1]}</p><a class="btn ghost" href="${url(stories[0][3])}">Prozkoumat ↗</a></article></div><div class="story-progress"><i id="story-progress"></i></div></div></div></div></section><section class="container section"><div class="section-head"><div><span class="eyebrow">NAJDI SVOU VÝZVU</span><h2 class="mt-4">Dnes podle tebe.</h2></div><a href="${url("/game-modes")}" class="btn ghost">Všechny herní módy ↗</a></div>${gameCards(5)}</section><section class="section" id="demo"><div class="container"><div class="section-head"><div><span class="eyebrow">TEĎ JSI NA ŘADĚ</span><h2 class="mt-4">Vyzkoušej Dartiqo.</h2></div><p>Klikni na terč. Zavři náhodné skóre třemi šipkami; poslední zásah musí být double.</p></div><div class="grid md:grid-cols-2 gap-10 items-center panel"><svg id="board" class="demo-board" viewBox="0 0 500 500" role="group" aria-label="Interaktivní šipkový terč"></svg><div><span class="eyebrow">CHECKOUT CHALLENGE</span><div id="score" class="text-8xl font-display font-bold text-accent my-5">81</div><p id="dart-count" class="text-sm">0 / 3 šipky</p><p id="demo-message" role="status" class="text-xs min-h-10 mt-3">Poslední šipka musí být double.</p><div class="flex gap-3 flex-wrap mt-5"><button class="btn" id="new-challenge">Nová výzva ↗</button><button class="btn ghost" id="checkout-hint">Ukázat cestu</button></div></div></div></div></section>${cta()}`}
function games(){return intro('HERNÍ MÓDY','Jedna vášeň.<br><span class="text-accent">Osm způsobů hry.</span>','Od klasické 501 po vlastní kariéru. Vyber režim a prozkoumej jeho nastavení.')+`<section class="container pb-24">${gameCards()}</section>`+cta()}
function modeDetail(id){const g=gameData.find(g=>g[0]===id)||gameData[0];return intro(g[4],g[1]+'.<br><span class="text-accent">Tvoje další výzva.</span>',g[2])+`<section class="container pb-24 grid lg:grid-cols-2 gap-6"><div class="panel"><span class="demo-badge">INTERAKTIVNÍ NASTAVENÍ · UKÁZKA</span><h3>Nastav si vlastní tempo</h3><label for="start-score">Výchozí skóre</label><select id="start-score"><option>301</option><option selected>501</option><option>701</option></select><label for="finish">Zakončení</label><select id="finish"><option>Double out</option><option>Straight out</option><option>Master out</option></select><label for="difficulty">${id==='dartbot'?'Úroveň bota':'Délka zápasu'}</label><select id="difficulty">${(id==='dartbot'?['Začátečník','Pokročilý','Expert']:['Na 1 vítězný leg','Na 3 vítězné legy','Na 5 vítězných legů']).map(v=>`<option>${v}</option>`).join('')}</select><button class="btn mt-6" data-demo="Nastavení je připravené. Spouštění plné hry není součástí designového dema.">Připravit zápas ↗</button></div><div class="panel flex flex-col justify-center text-center"><span class="eyebrow">${g[1]} / NÁHLED</span><div class="text-8xl font-display font-bold text-accent my-8" id="config-preview">${id==='cricket'?'20 · 19':'501'}</div><span id="config-caption" class="pill mx-auto">Double out</span><p class="text-xs mt-6">Alex vs ${id==='dartbot'?'DartBot':'Sam'} · Ukázkoví hráči</p></div><article class="panel lg:col-span-2"><h3>Jak se hraje</h3><div class="grid md:grid-cols-3 gap-7 mt-5">${(id==='cricket'?['Uzavírej čísla 15 až 20 a bull třemi zásahy.','Na čísle, které soupeř ještě neuzavřel, můžeš bodovat.','Vyhraješ po uzavření všech cílů, pokud nemáš méně bodů.']:['V jednom tahu máš tři šipky. Každý zásah ovlivní tvoje skóre.','V X01 odečítáš body a musíš dosáhnout přesně nuly.','Způsob zakončení určuje nastavení. Double out vyžaduje double.']).map((v,i)=>`<div><span class="text-accent text-xs">0${i+1}</span><p class="text-sm mt-3">${v}</p></div>`).join('')}</div><p class="demo-note">Konfigurátor ukazuje podobu nastavení. ${g[1]} je připravovaný režim; skutečný zápas se zde nespouští.</p></article></section>`}
const trainings=[['Around the Clock','Přesnost','Postupně zasáhni čísla 1 až 20.'],["Bob’s 27",'Doubly','Začni na 27 bodech a projdi doubly.'],['121 Checkout','Zavírání','Zkus zavřít 121 na devět šipek.'],['Shanghai','Přesnost','Single, double, triple jednoho čísla.'],['Halve-It','Přesnost','Plň cíle, jinak se skóre půlí.'],['Doubles Training','Doubly','Soustřeď se na rozhodující kruh.'],['Scoring Practice','Skórování','Najdi konzistentní rytmus.'],['Checkout Practice','Zavírání','Trénuj cestu k poslednímu doublu.'],['Accuracy Challenge','Přesnost','Méně rozptylu, více jistoty.'],['Pressure Training','Zavírání','Tři šipky. Jeden pokus.']];function trainingCards(cat='Vše'){return trainings.filter(t=>cat==='Vše'||t[1]===cat).map((t,i)=>`<button class="panel text-left hover:border-accent" data-training="${escapeHtml(t[0])}"><span class="eyebrow">${t[1]}</span><div class="text-accent text-4xl my-5">${['◎','27','121','Ⅲ'][i%4]}</div><h3>${t[0]}</h3><p class="text-xs mt-3">${t[2]}</p><span class="text-xs inline-block mt-5">Detail tréninku ↗</span></button>`).join('')}
const heatmap=()=>`<div class="heatmap" aria-label="Ukázková tepelná mapa zásahů">${Array.from({length:50},(_,i)=>`<i style="opacity:${.15+((i*17)%80)/100}"></i>`).join('')}</div>`;function training(){return intro('TRAINING LAB','Trénuj chytřeji.<br><span class="text-accent">Házej lépe.</span>','Deset cest, jak proměnit další trénink v konkrétní posun.')+`<section class="container pb-24"><div class="flex flex-wrap gap-2 mb-7">${['Vše','Přesnost','Doubly','Zavírání','Skórování'].map((n,i)=>`<button class="chip ${i===0?'active':''}" data-training-filter="${n}">${n}</button>`).join('')}</div><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4" id="training-list">${trainingCards()}</div></section><section class="container section" id="coach"><div class="panel grid md:grid-cols-2 gap-10"><div><span class="demo-badge">AI COACH · SIMULOVANÁ ANALÝZA</span><h2>Ví, kam<br>mířit příště.</h2><p class="text-sm mt-5">Prohlédni si ukázku doporučení podle modelových tréninkových dat.</p><select id="coach-select" class="mt-5"><option value="double">Zlepšit doubly</option><option value="score">Zlepšit skórování</option></select><p id="coach-advice" class="mt-5 text-sm">V ukázkových datech je D16 méně úspěšný než D20. Zkus deset minut cíleného tréninku D16.</p></div><div>${heatmap()}<div class="grid grid-cols-2 gap-3 mt-6"><div class="panel !p-4"><span class="eyebrow">PŘESNOST</span><div class="kpi">68 %</div></div><div class="panel !p-4"><span class="eyebrow">POSUN</span><div class="kpi">+12 %</div></div></div></div></div></section>`}
const levels=['Amatér','Lokální soutěže','Regionální turnaje','Národní úroveň','Profesionální okruh','Světová špička'];function career(){return intro('TVŮJ VLASTNÍ PŘÍBĚH','Od první šipky<br><span class="text-accent">až na vrchol.</span>','Reálné výsledky, herní postup a další cíl na obzoru. Prozkoumej návrh kariérního světa.')+`<section class="container pb-24"><div class="grid lg:grid-cols-[1.5fr_1fr] gap-6"><div class="career-map">${levels.map((l,i)=>`<button class="career-node ${i===1?'active':''}" data-level="${i}"><strong>${['◎','⚑','♜','★','♛','✦'][i]}</strong><span class="text-xs">${l}</span><small class="text-[9px] text-zinc-500">LEVEL ${i*10+1}</small></button>`).join('')}</div><div class="panel" id="career-detail"></div></div><div class="grid md:grid-cols-3 gap-4 mt-6"><div class="panel"><span class="eyebrow">PROFIL HRÁČE · DEMO</span><h3 class="mt-4">Alex / Level 12</h3><div class="strength"><i style="width:64%"></i></div><p class="text-xs mt-3">640 / 1 000 XP</p></div><div class="panel"><span class="eyebrow">DALŠÍ TURNAJ · UKÁZKA</span><h3 class="mt-4">Páteční pohár</h3><p class="text-xs mt-3">16. října · 18:00 · 16 hráčů</p></div><div class="panel"><span class="eyebrow">SBÍRKA</span><div class="text-accent text-4xl mt-4">♜ ✦ ⚑</div><p class="text-xs mt-3">První výhra · 100 her · První turnaj</p></div></div></section>`}
const players=[['Niko180',68.2,'Ranked'],['DoubleQueen',61.7,'Přátelský'],['BullseyeTom',74.1,'Ranked'],['MiaDarts',55.3,'Přátelský']];const lobbyRows=(f='Vše')=>players.filter(p=>f==='Vše'||p[2]===f).map((p,i)=>`<article class="panel flex items-center gap-4"><div class="rounded-full bg-accent text-black w-11 h-11 flex items-center justify-center font-bold">${p[0][0]}</div><div class="flex-1"><h3 class="!text-base">${p[0]}</h3><p class="text-xs">${p[2]} · 501 · Ø ${p[1]}</p></div><button class="btn" data-demo="Ukázka pozvánky pro ${p[0]}. Toto lobby neobsahuje skutečné online hráče.">Vyzvat ↗</button></article>`).join('');function online(){return intro('ONLINE / LOBBY','Soupeři<br><span class="text-accent">nečekají.</span>','Přátelský zápas, ranked nebo turnaj. Tady začíná společná hra.')+`<section class="container pb-24"><span class="demo-badge">VŠICHNI HRÁČI A STATUSY JSOU DEMONSTRAČNÍ</span><div class="grid lg:grid-cols-[1.5fr_1fr] gap-7"><div><div class="flex gap-2 mb-5">${['Vše','Ranked','Přátelský'].map((n,i)=>`<button class="chip ${i===0?'active':''}" data-lobby="${n}">${n}</button>`).join('')}</div><div class="grid gap-3" id="lobby">${lobbyRows()}</div></div><div class="panel"><span class="eyebrow">TVŮJ DALŠÍ SOUBOJ</span><h2 class="my-6">Najdi<br>svůj match.</h2><label for="match-type">Typ zápasu</label><select id="match-type"><option>Ranked · 501</option><option>Přátelský · 301</option></select><button class="btn w-full mt-6" id="matchmaking">Vyzkoušet hledání ↗</button><p id="match-state" class="text-xs mt-4" role="status">Simulace hledání soupeře.</p><a href="${url("/leaderboards")}" class="text-xs text-accent inline-block mt-5">Prohlédnout žebříčky ↗</a></div></div></section>`}
const periods={'7 dní':[45,52,49,61,55,64,68],'30 dní':[39,46,43,52,55,58,64],'90 dní':[32,36,44,42,51,57,62]};function chart(period='30 dní'){return `<div class="chart">${periods[period].map((v,i)=>`<button style="height:${v*1.3}%" aria-label="Období ${i+1}: průměr ${v}"><span>${v} bodů</span></button>`).join('')}</div><div class="flex justify-between text-[9px] text-zinc-500 mt-3"><span>ZAČÁTEK OBDOBÍ</span><span>DNES</span></div>`}function statistics(){return intro('TVŮJ VÝKON POD LUPOU','Každý hod<br><span class="text-accent">vypráví příběh.</span>','Interaktivní přehled modelových výsledků. Přepni období a prohlédni si vývoj.')+`<section class="container pb-24"><div class="flex gap-2 mb-6">${Object.keys(periods).map(n=>`<button class="chip ${n==='30 dní'?'active':''}" data-period="${n}">${n}</button>`).join('')}</div><span class="demo-badge">UKÁZKOVÁ DATA</span><div class="grid-kpi" id="kpis"></div><div class="grid md:grid-cols-2 gap-5 mt-5"><div class="panel"><h3>Vývoj průměru</h3><div id="stats-chart">${chart()}</div></div><div class="panel"><h3>Přesnost zásahů</h3>${heatmap()}<p class="text-xs mt-4">Světlá pole představují častější zásahy v této ukázce.</p></div></div><div class="panel mt-5"><h3>Poslední zápasy</h3>${['DartBot / 3:1 / 61.2','Niko180 / 2:3 / 58.4','DoubleQueen / 3:0 / 65.1'].map(x=>`<div class="mini-row !text-sm"><span>${x.split(' / ')[0]}</span><span>${x.split(' / ')[1]}</span><span>Ø ${x.split(' / ')[2]}</span></div>`).join('')}</div></section>`}
function appPage(){return intro('UKÁZKOVÝ ÚČET',`Ahoj, ${escapeHtml(profile.first)}.<br><span class="text-accent">Dnes míříš výš.</span>`,'Vítej v interaktivním demo dashboardu. Výsledky jsou modelové.')+`<section class="container pb-24"><nav class="app-nav"><a class="chip active" href="${url("/app")}">Přehled</a><a class="chip" href="${url("/app/profile")}">Profil</a><a class="chip" href="${url("/app/settings")}">Nastavení</a></nav><div class="grid md:grid-cols-3 gap-5"><div class="panel md:col-span-2 !bg-accent !text-black"><span class="eyebrow !text-black/60">LEVEL 12 / TVOJE DALŠÍ VÝZVA</span><h2 class="my-6">Jedna hra.<br>Nová osobní výhra.</h2><a class="btn !bg-black !text-white" href="${url("/game-modes/x01")}">Rychlá hra ↗</a></div><div class="panel"><h3>${escapeHtml(profile.username)}</h3><div class="text-6xl text-accent my-5">⚑</div><p class="text-xs">640 / 1 000 XP</p><div class="strength"><i style="width:64%"></i></div></div></div><div class="grid-kpi mt-5">${[['Průměr','58.4'],['Checkout','32 %'],['Výhry','64 %'],['Nejvyšší zavření','121']].map(([n,v])=>`<div class="panel"><span class="eyebrow">${n}</span><div class="kpi">${v}</div></div>`).join('')}</div><div class="grid md:grid-cols-3 gap-5 mt-5">${[['Trénink','Dnes zkus D16.','/training'],['Kariéra','Páteční pohár čeká.','/career'],['Online','Najdi další výzvu.','/online']].map(([n,p,u])=>`<a class="panel" href="${url(u)}"><h3>${n} ↗</h3><p class="text-sm mt-3">${p}</p></a>`).join('')}</div><div class="panel mt-5"><h3>Poslední zápasy</h3><div class="table-row"><b>DartBot</b><span>3 : 1</span><span>Ø 61.2</span><span>Výhra</span></div><div class="table-row"><b>Niko180</b><span>2 : 3</span><span>Ø 58.4</span><span>Prohra</span></div></div></section>`}
const field=(id,label,type='text',value='',attrs='')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${escapeHtml(value)}" ${attrs}>`;const passwordField=(id,label)=>`<label for="${id}">${label}</label><div class="password-wrap"><input id="${id}" type="password" minlength="12" maxlength="128" autocomplete="new-password" required><button type="button" data-password="${id}">Ukázat</button></div>`;const socials=()=>`<div class="grid grid-cols-2 gap-3"><button type="button" class="social" data-social="Apple">● Apple</button><button type="button" class="social" data-social="Facebook">f Facebook</button></div>`;function authShell(inner,register=false){return `<main class="auth-shell"><aside class="auth-art">${brand()}<span class="eyebrow mt-12">${register?'NOVÝ HRÁČ. NOVÝ PŘÍBĚH.':'TVŮJ DALŠÍ LEG ČEKÁ.'}</span><h2 class="mt-5">${register?'Tvůj odkaz.<br><span class="text-accent">Začíná tady.</span>':'Zpátky ve hře.<br><span class="text-accent">Ve svém rytmu.</span>'}</h2>${register?'<div class="register-trophy" aria-hidden="true">♜</div>':phone(0)}<p class="text-xs mt-auto">Dartiqo / Hraj. Trénuj. Soutěž.</p></aside><section class="auth-form"><div class="flex justify-between items-center mb-5"><a href="${url("/")}" class="text-xs text-zinc-500">← Zpět na úvod</a><button class="icon-btn" data-theme aria-label="Přepnout vzhled">◐</button></div>${inner}</section></main>`}
function login(){return authShell(`<span class="eyebrow">VÍTEJ ZPÁTKY</span><h1>Zpátky do hry.</h1><p class="text-xs mb-6">Další dobrý hod začíná tady.</p>${socials()}<div class="text-center text-[10px] text-zinc-500 my-5">NEBO PŘES SVŮJ ÚČET</div><form id="login-form">${field('identity','E-mail nebo uživatelské jméno','text','','required autocomplete="username"')}${passwordField('login-password','Heslo')}<div class="flex items-center justify-between mt-4 text-[10px]"><label class="!m-0 flex gap-2"><input type="checkbox"> Zapamatovat si mě</label><a class="text-accent" href="${url("/forgot-password")}">Zapomenuté heslo?</a></div><button class="btn w-full mt-6" type="submit">Přihlásit se ↗</button><p id="auth-feedback" class="hint" role="status"></p></form><p class="text-xs mt-5 text-center">Ještě nemáš účet? <a href="${url("/register")}" class="text-accent">Registrovat se</a></p><p class="demo-note">Frontendové demo. Údaje se nikam neodesílají. Pro úspěšný demo stav použij libovolné jméno a heslo alespoň 12 znaků.</p>`)}
let regStep=0,reg={first:'',last:'',username:'',email:'',password:'',confirm:'',avatar:'🎯',zoom:1,x:0,y:0};function register(){return authShell('<div id="register-content"></div>',true)}function avatarMarkup(){return reg.photo?`<img src="${url(reg.photo)}" alt="Náhled profilové fotky" style="transform:translate(${reg.x}px,${reg.y}px) scale(${reg.zoom})">`:`<span>${reg.avatar}</span>`}function renderRegister(){const names=['Vyber si cestu','Jak ti máme říkat?','Tvoje hráčské jméno','Kam ti můžeme napsat?','Heslo, které drží.','Ukaž svou tvář.','Je to tvoje.'];$('#register-content').innerHTML=`<span class="eyebrow">${regStep?'KROK '+regStep+' / 6':'VÍTEJ V DARTIQO'}</span><h1>${names[regStep]}</h1><div class="progress">${Array.from({length:6},(_,i)=>`<i class="${i<regStep?'done':''}"></i>`).join('')}</div><form id="register-form" novalidate>${regStep===0?`${socials()}<button type="button" class="btn w-full mt-5" id="email-register">Pokračovat e-mailem ↗</button><p class="text-xs text-center mt-5">Už máš účet? <a href="${url("/login")}" class="text-accent">Přihlásit se</a></p>`:regStep===1?field('first','Jméno','text',reg.first,'required autocomplete="given-name"')+field('last','Příjmení','text',reg.last,'required autocomplete="family-name"'):regStep===2?field('username','Uživatelské jméno','text',reg.username,'required minlength="3" maxlength="24" autocomplete="username"')+'<p class="hint">3–24 znaků: písmena, čísla a podtržítko. Dostupnost je simulovaná.</p><div id="username-alts" class="flex gap-2 mt-3"></div>':regStep===3?field('email','E-mail','email',reg.email,'required autocomplete="email"'):regStep===4?passwordField('password','Heslo')+passwordField('confirm','Potvrzení hesla')+'<div class="strength"><i id="strength-bar" style="width:0"></i></div><p id="strength-text" class="hint">Síla hesla</p><p id="password-length" class="hint">○ 12 až 128 znaků</p><p id="password-match" class="hint">○ Hesla se shodují</p>':regStep===5?`<div class="avatar-crop" id="avatar-preview">${avatarMarkup()}</div><label class="social mt-5 cursor-pointer" id="drop-zone">Nahrát nebo přetáhnout fotku<input id="avatar-upload" type="file" accept="image/*" class="hidden"></label><label for="avatar-zoom">Přiblížení · fotku posuň tažením</label><input type="range" id="avatar-zoom" min="1" max="2.5" step=".05" value="${reg.zoom}"><div class="flex justify-center gap-3 mt-5">${['🎯','⚡','♜','★'].map(a=>`<button type="button" class="icon-btn" data-avatar="${a}">${a}</button>`).join('')}</div><button type="button" class="text-xs text-zinc-500 block mx-auto mt-4" id="skip-avatar">Přeskočit tento krok →</button>`:`<div class="panel !p-5"><div class="avatar-crop !w-20 !h-20">${avatarMarkup()}</div><h3 class="mt-4 text-center">${escapeHtml(reg.first)} ${escapeHtml(reg.last)}</h3><p class="text-xs text-center">@${escapeHtml(reg.username)}<br>${escapeHtml(reg.email)}</p></div><label class="flex gap-3 items-start text-[11px]"><input type="checkbox" id="terms"> Souhlasím s ukázkovými podmínkami <button type="button" class="text-accent" data-legal="Podmínky">↗</button></label><label class="flex gap-3 items-start text-[11px]"><input type="checkbox" id="privacy"> Seznámil/a jsem se se zásadami soukromí <button type="button" class="text-accent" data-legal="Soukromí">↗</button></label><label class="flex gap-3 items-start text-[11px]"><input type="checkbox"> Chci novinky od Dartiqo (nepovinné)</label>`}<p id="register-status" class="hint min-h-5" role="status"></p>${regStep?`<div class="flex gap-3 mt-5"><button type="button" class="btn ghost" id="reg-back">←</button><button class="btn flex-1" type="submit">${regStep===6?'Vytvořit demo účet':'Pokračovat'} ↗</button></div>`:''}</form><p class="demo-note">Pouze lokální ukázka registrace. Žádný skutečný účet nevzniká.</p>`;bindCommon($('#register-content'));if(regStep===0){$('#email-register').onclick=()=>{regStep=1;renderRegister()};return}$('#reg-back').onclick=()=>{saveRegFields();regStep--;renderRegister()};if(regStep===4){$('#password').value=reg.password;$('#confirm').value=reg.confirm}$('#register-form').oninput=()=>{saveRegFields();validateReg(false)};$('#register-form').onsubmit=e=>{e.preventDefault();saveRegFields();if(!validateReg(true))return;if(regStep===6){finishRegistration();return}regStep++;renderRegister()};if(regStep===5)bindAvatar();validateReg(false)}
function saveRegFields(){['first','last','username','email','password','confirm'].forEach(k=>{if($('#'+k))reg[k]=$('#'+k).value})}function validateReg(show){let msg='',ok=true;if(regStep===1){ok=reg.first.trim().length>0&&reg.last.trim().length>0;msg=ok?'✓ Jméno je připravené.':'Vyplň jméno a příjmení.'}if(regStep===2){const taken=['admin','dartiqo','alex','player'];ok=/^[a-zA-Z0-9_]{3,24}$/.test(reg.username)&&!taken.includes(reg.username.toLowerCase());msg=ok?'✓ V demo seznamu je jméno dostupné.':taken.includes(reg.username.toLowerCase())?'Toto jméno je v demo seznamu obsazené.':'Použij 3–24 písmen, číslic nebo podtržítek.';$('#username-alts').innerHTML=taken.includes(reg.username.toLowerCase())?['180','_darts','26'].map(x=>`<button class="chip" type="button" data-alt="${reg.username+x}">${reg.username+x}</button>`).join(''):'';$$('[data-alt]').forEach(b=>b.onclick=()=>{$('#username').value=b.dataset.alt;saveRegFields();validateReg(false)})}if(regStep===3){ok=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(reg.email);msg=ok?'✓ Formát e-mailu je v pořádku.':'Zadej platný formát e-mailu.'}if(regStep===4){const len=reg.password.length>=12&&reg.password.length<=128,match=reg.password===reg.confirm&&reg.confirm.length>0;ok=len&&match;let strength=reg.password.length<12?0:Math.min(3,(reg.password.length>=16?1:0)+(/[^a-zA-Z0-9]/.test(reg.password)?1:0)+(/[0-9]/.test(reg.password)&&/[A-Z]/.test(reg.password)?1:0));$('#strength-bar').style.width=reg.password.length?((strength+1)*25)+'%':'0%';$('#strength-text').textContent=['Slabé','Přijatelné','Silné','Velmi silné'][strength];$('#password-length').textContent=(len?'✓':'○')+' 12 až 128 znaků';$('#password-length').className='hint '+(len?'good':'');$('#password-match').textContent=(match?'✓':'○')+' Hesla se shodují';$('#password-match').className='hint '+(match?'good':'');msg=ok?'✓ Heslo je připravené.':'Zkontroluj délku hesla a jeho potvrzení.'}if(regStep===6){ok=$('#terms').checked&&$('#privacy').checked;msg=ok?'✓ Vše je připravené.':'Pro pokračování potvrď oba povinné body.'}const status=$('#register-status');status.textContent=ok?msg:show?msg:'';status.className='hint min-h-5 '+(ok?'good':show?'error':'');return ok}
function bindAvatar(){const render=()=>$('#avatar-preview').innerHTML=avatarMarkup();function load(file){if(!file)return;if(!file.type.startsWith('image/')||file.size>5*1024*1024){toast('Vyber obrázek do 5 MB.');return}const reader=new FileReader();reader.onload=()=>{reg.photo=reader.result;reg.zoom=1;reg.x=0;reg.y=0;render()};reader.readAsDataURL(file)}$('#avatar-upload').onchange=e=>load(e.target.files[0]);const drop=$('#drop-zone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('border-accent')};drop.ondragleave=()=>drop.classList.remove('border-accent');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('border-accent');load(e.dataTransfer.files[0])};$('#avatar-zoom').oninput=e=>{reg.zoom=+e.target.value;const bound=64*(reg.zoom-1);reg.x=Math.max(-bound,Math.min(bound,reg.x));reg.y=Math.max(-bound,Math.min(bound,reg.y));render()};$$('[data-avatar]').forEach(b=>b.onclick=()=>{reg.photo=null;reg.avatar=b.dataset.avatar;render()});$('#skip-avatar').onclick=()=>{regStep=6;renderRegister()};let drag;const crop=$('#avatar-preview');crop.onpointerdown=e=>{if(!reg.photo)return;drag={x:e.clientX,y:e.clientY,ox:reg.x,oy:reg.y};crop.setPointerCapture(e.pointerId)};crop.onpointermove=e=>{if(!drag)return;const bound=64*(reg.zoom-1);reg.x=Math.max(-bound,Math.min(bound,drag.ox+e.clientX-drag.x));reg.y=Math.max(-bound,Math.min(bound,drag.oy+e.clientY-drag.y));render()};crop.onpointerup=()=>drag=null;crop.onpointercancel=()=>drag=null}
function finishRegistration(){profile={first:reg.first,last:reg.last,username:reg.username,email:reg.email,avatar:reg.avatar};if(reg.photo){const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d'),scale=Math.max(128/img.width,128/img.height)*reg.zoom;ctx.drawImage(img,(128-img.width*scale)/2+reg.x,(128-img.height*scale)/2+reg.y,img.width*scale,img.height*scale);profile.photo=c.toDataURL('image/jpeg',.8);saveProfile()};img.src=reg.photo}else saveProfile();reg.password=reg.confirm='';$('#register-content').innerHTML=`<div class="text-center py-10 fade-in"><div class="text-accent text-8xl mb-7">✓</div><span class="eyebrow">DEMO PROFIL PŘIPRAVEN</span><h1>Vítej ve hře,<br>${escapeHtml(profile.first)}.</h1><p class="text-xs mb-7">Tvoje ukázková kariéra může začít.</p><a class="btn" href="${url("/app")}">Vstoupit do Dartiqo ↗</a></div>`}function saveProfile(){try{sessionStorage.setItem('dartiqo-demo-profile',JSON.stringify(profile))}catch{}}
function recovery(reset){return authShell(`<span class="eyebrow">${reset?'NOVÝ ZAČÁTEK':'ZPÁTKY K ÚČTU'}</span><h1>${reset?'Nové heslo.':'Zapomenuté heslo?'}</h1><p class="text-xs mb-5">${reset?'Vytvoř nové heslo o délce 12 až 128 znaků.':'Zadej e-mail a prohlédni si ukázku obnovení.'}</p><form id="recovery-form">${reset?passwordField('reset-pass','Nové heslo')+passwordField('reset-confirm','Potvrzení hesla'):field('recovery-email','E-mail','email','','required')}<button class="btn w-full mt-6">${reset?'Změnit heslo':'Obnovit heslo'} ↗</button><p id="recovery-status" class="hint" role="status"></p></form><a href="${url("/login")}" class="text-xs text-accent block mt-6">Zpět na přihlášení</a><p class="demo-note">Designové demo. Žádný e-mail se neposílá a heslo se ve skutečnosti nemění.</p>`)}
function settings(isProfile){return intro('DEMO ÚČET',isProfile?'Tvůj hráčský profil.':'Všechno podle tebe.','Změny zůstanou jen v této lokální ukázce.')+`<section class="container pb-24 max-w-3xl"><nav class="app-nav"><a class="chip" href="${url("/app")}">Přehled</a><a class="chip" href="${url("/app/profile")}">Profil</a><a class="chip" href="${url("/app/settings")}">Nastavení</a></nav><form class="panel" id="profile-form">${isProfile?`<div class="avatar-crop" id="profile-avatar">${profile.photo?`<img src="${url(profile.photo)}" alt="Avatar">`:`<span>${profile.avatar}</span>`}</div><label class="social mt-4 cursor-pointer">Změnit fotografii<input class="hidden" type="file" accept="image/*" id="profile-photo"></label>${field('profile-first','Jméno','text',profile.first,'required')}${field('profile-last','Příjmení','text',profile.last,'required')}${field('profile-user','Uživatelské jméno','text',profile.username,'required pattern="[a-zA-Z0-9_]{3,24}"')}`:`<h3>Vzhled a notifikace</h3><button type="button" data-theme class="btn ghost mt-5">Přepnout světlý / tmavý režim ◐</button><label class="flex gap-3 items-center"><input type="checkbox" id="notify-demo" checked> Připomínky tréninku</label><label class="flex gap-3 items-center"><input type="checkbox" id="news-demo"> Novinky z Dartiqo</label><h3 class="mt-7">Propojené účty</h3><div class="grid gap-3 mt-4">${socials()}</div><a href="${url("/reset-password")}" class="text-xs text-accent block mt-6">Změnit heslo ↗</a>`}<button class="btn mt-7" type="submit">Uložit demo změny ↗</button></form></section>`}
