function bindCommon(scope=document){$$('button[data-theme]',scope).forEach(b=>b.onclick=e=>{e.stopPropagation();if(document.documentElement.classList.contains('theme-switching'))return;const change=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('dartiqo-design-theme',theme)}catch{}};if(document.startViewTransition&&!reduced){const rect=b.getBoundingClientRect(),x=rect.left+rect.width/2,y=rect.top+rect.height/2,r=Math.hypot(Math.max(x,innerWidth-x),Math.max(y,innerHeight-y)),root=document.documentElement;root.style.setProperty('--theme-x',x+'px');root.style.setProperty('--theme-y',y+'px');root.style.setProperty('--theme-r',Math.ceil(r)+'px');root.classList.add('theme-switching');const transition=document.startViewTransition(change);transition.finished.finally(()=>root.classList.remove('theme-switching'))}else change()});$$('[data-password]',scope).forEach(b=>b.onclick=()=>{const input=$('#'+b.dataset.password);input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Ukázat':'Skrýt'});$$('[data-social]',scope).forEach(b=>b.onclick=()=>modal('Přihlášení přes '+b.dataset.social,'Toto je designová ukázka. Propojení s '+b.dataset.social+' není aktivní. Můžeš pokračovat e-mailem nebo otevřít <a class="text-accent" href="'+url("/app")+'">demo dashboard</a>.'));$$('[data-demo]',scope).forEach(b=>b.onclick=()=>toast(b.dataset.demo));$$('[data-legal]',scope).forEach(b=>b.onclick=()=>modal(b.dataset.legal,'Toto jsou pouze ukázkové souhlasy pro návrh formuláře, nikoli skutečné smluvní podmínky. V produkční aplikaci zde bude příslušný dokument.'))}bindCommon();
