// One frame-scheduled scroll update for the outer frame and pinned product story.
let storyIndex=0,scrollScheduled=false;
function renderStory(index){if(index===storyIndex)return;storyIndex=index;$('#story-screen').innerHTML=phoneUI(stories[index][2]);$('#story-copy-content').innerHTML=`<article class="story-active"><span class="eyebrow">0${index+1} / DARTIQO</span><h3>${stories[index][0]}</h3><p>${stories[index][1]}</p><a class="btn ghost" href="${url(stories[index][3])}">Prozkoumat ↗</a></article>`;$$('[data-story-jump]').forEach(b=>{const active=+b.dataset.storyJump===index;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)})}
function updateScrollComposition(){scrollScheduled=false;if(route!=='/')return;const base=innerWidth<768?12:32;const progress=Math.min(1,Math.max(0,scrollY/Math.max(360,innerHeight*.65)));document.body.style.setProperty('--frame-width',(base*(1-progress)).toFixed(2)+'px');const track=$('#story-track');if(track){const travel=Math.max(1,track.offsetHeight-$('.story-stage').offsetHeight);const p=Math.max(0,Math.min(1,(100-track.getBoundingClientRect().top)/travel));renderStory(Math.min(stories.length-1,Math.floor(p*stories.length)));$('#story-progress').style.width=(p*100)+'%'}}
function queueScrollComposition(){if(!scrollScheduled){scrollScheduled=true;requestAnimationFrame(updateScrollComposition)}}
addEventListener('scroll',queueScrollComposition,{passive:true});addEventListener('resize',queueScrollComposition);$$('[data-story-jump]').forEach(b=>b.onclick=()=>{const track=$('#story-track');const travel=Math.max(1,track.offsetHeight-$('.story-stage').offsetHeight);const index=+b.dataset.storyJump;scrollTo({top:scrollY+track.getBoundingClientRect().top-100+travel*(index+.25)/stories.length,behavior:reduced?'instant':'smooth'})});updateScrollComposition();
